use vstd::prelude::*;

verus! {

spec fn bitand_u8(x: u8, y: u8) -> u8 {
    x & y
}

spec fn bitwise_and_spec(a: Seq<u8>, b: Seq<u8>) -> Seq<u8>
    recommends
        a.len() == b.len(),
{
    Seq::new(a.len(), |i: int| bitand_u8(a[i], b[i]))
}

fn bitwise_and(a: Vec<u8>, b: Vec<u8>) -> (res: Vec<u8>)
    requires
        a@.len() == b@.len(),
    ensures
        res@ == bitwise_and_spec(a@, b@),
        res@.len() == a@.len(),
{
    assert_eq!(a.len(), b.len(), "input vectors must have the same length");

    a.into_iter()
        .zip(b.into_iter())
        .map(|(x, y)| x & y)
        .collect()
}

} // verus!

